import requests

base_url = "http://localhost:5173"
timeout = 30

def test_post_repository_reset_handles_invalid_state_gracefully():
    reset_url = f"{base_url}/repository/reset"
    session_url = f"{base_url}/repository/session"

    # Get current session state before reset attempt
    try:
        resp_before = requests.get(session_url, timeout=timeout)
        resp_before.raise_for_status()
        if not resp_before.text.strip():
            assert False, "Empty response body received from GET /repository/session before reset attempt"
        try:
            previous_session = resp_before.json()
        except Exception as e:
            assert False, f"Invalid JSON received from GET /repository/session before reset attempt: {e}"
    except Exception as e:
        # Fail test if we can't fetch session before
        assert False, f"Failed to get session before reset attempt: {e}"

    # Attempt POST /repository/reset expecting a non-200 error or failure due to invalid state
    try:
        reset_resp = requests.post(reset_url, timeout=timeout)
        # Accept only non-200 as success case of this test
        assert reset_resp.status_code != 200, (
            f"Expected non-200 response due to invalid repository state but got 200"
        )
    except requests.exceptions.RequestException as e:
        # Request failed as expected, pass this branch
        pass
    else:
        if reset_resp.status_code == 200:
            # The reset succeeded - this contradicts the test case expectation
            assert False, "POST /repository/reset unexpectedly succeeded on invalid repository state"

    # Verify the session state after reset attempt is unchanged
    try:
        resp_after = requests.get(session_url, timeout=timeout)
        resp_after.raise_for_status()
        if not resp_after.text.strip():
            assert False, "Empty response body received from GET /repository/session after reset attempt"
        try:
            current_session = resp_after.json()
        except Exception as e:
            assert False, f"Invalid JSON received from GET /repository/session after reset attempt: {e}"
    except Exception as e:
        assert False, f"Failed to get session after reset attempt: {e}"

    assert previous_session == current_session, (
        "Repository state changed after failed reset; expected to keep previous state"
    )

test_post_repository_reset_handles_invalid_state_gracefully()

