import requests

BASE_URL = "http://localhost:5173"
TIMEOUT = 30

def test_postserviceoverlayshowignoresrequestbeforetimelimitreached():
    url = f"{BASE_URL}/service/overlay/show"
    headers = {
        "Content-Type": "application/json"
    }

    try:
        response = requests.post(url, headers=headers, timeout=TIMEOUT)
    except requests.RequestException as e:
        assert False, f"Request failed due to an exception: {e}"

    # According to PRD, the response with 200 is 'success' (likely plain text), else non-200 implies ignore via failure
    if response.status_code == 200:
        # Assert exact text 'success' case-insensitive
        assert response.text.strip().lower() == "success", f"Expected exact 'success' in response body, got: {response.text}"
    else:
        # Should not be 200, i.e. ignored or failed
        assert response.status_code != 200

test_postserviceoverlayshowignoresrequestbeforetimelimitreached()
